def solve_case(case):
    nums = case.get('nums', [])
    target = case.get('target', 0)
    if len(nums) < 2:
        return False
    seen = set()
    for x in nums:
        if target - x in seen:
            return True
        seen.add(x)
    return False

def solve_case(case):
    coins = case.get('coins', [])
    amount = case.get('amount', 0)
    if amount == 0:
        return 0
    uniq = list(set(coins))
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in uniq:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return -1 if dp[amount] > amount else dp[amount)

def solve_case(case):
    s = case.get("s", "")
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    left = {'(', '[', '{'}
    for ch in s:
        if ch in left:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

def solve_case(case):
    nums = case.get('nums', [])
    if not nums:
        return 0
    tails = []
    for x in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid
        if left == len(tails):
            tails.append(x)
        else:
            tails[left] = x
    return len(tails)
